        put("flat bench leg raise", ExerciseWhy(purpose = "Lifts straight legs off a bench to work the abs and hip flexors, with the abs holding the pelvis against the leg load.", pickIt = "Pick it as an easier step toward hanging leg raises since you are supported; keep the lower back from arching or lower the legs less far.", tags = listOf("Abs", "Hip flexors", "Beginner-friendly")))
