        put("abdominal draw-in", ExerciseWhy(purpose = "Pulls the belly in toward the spine on all fours, a low-load drill for the deep abdominal wall and trunk control.", pickIt = "Pick it to learn bracing before harder core work; it is too light to build much strength, so progress to dead bugs or planks.", tags = listOf("Core control", "Bracing", "Beginner-friendly")))
        put("barbell rear delt row", ExerciseWhy(purpose = "Rows a barbell to the chest with a wide grip and flared elbows, biasing the rear delts and upper back.", pickIt = "Pick it for the heaviest rear delt loading; it needs a held bent-over position, so use the Smith or supported version if your back tires.", tags = listOf("Rear delts", "Upper back", "Heavy loading")))
