        put("dumbbell squat", ExerciseWhy(purpose = "Squats while holding dumbbells at the sides, loading the quads and glutes with the adductors helping.", pickIt = "Pick it when you have no rack or are learning the squat; dumbbells cap the load, so use goblet or barbell squats for heavy work.", tags = listOf("Quads", "Glutes", "Easy setup")))
